'use client';
// © 2026 Dr. Ahmed Mohamed Abdelaziz Badawi — All rights reserved. See COPYRIGHT.md
/**
 * P46 ر3 «محور التقارير» — تقرير إنجاز المهمة («أثرُ المهمة») للخبير/المستشار/المدرّب المتعاقد
 *  <MissionCards>   داخل /me/reports            «مهماتك الموقَّعة»: بطاقة لكل عقد تعاون (هيئة أَثَر) + «ابدأ تقرير إنجاز المهمة» أو فتحه
 *  <MissionEditor>  /me/reports/[id] · /admin   تسعة أقسام: بيانات المهمة من العقد · ملخّص · «الوعد مقابل الواقع» · «خطّ المهمة» · النتائج والأثر · التوصيات · الدروس · التسليم · الاعتماد
 *  <MissionDoc>     المطبوع A4 + ما تراه الجهة   وثيقة واحدة للقراءة (بلا الملاحظة الإدارية للجهة · بلا أجر في أي مكان)
 *  <MissionClient>  /verify/report/[code]?k=     الجهة تقرأ وتضغط «أقرّ بالاستلام» — بلا دخول
 *  الذكاء الاصطناعي يصوغ من حالات المخرجات والمراحل فقط؛ الحكم والتوصية للخبير؛ الاعتماد للطاقم؛ الإقرار للجهة.
 *  ر3-ب: يُكتب أيضًا لطلب استشارة بلا عقد؛ كل مخرج يمكن ربطه بوثيقة أَثَر معتمَدة (رأي · دراسة) = «سلسلة الوثائق»؛ والبطاقات انتقلت إلى <WorkCards> في AdvisoryReport.
 */
import { useCallback, useEffect, useMemo, useState } from 'react';
import Link from 'next/link';
import { Icon } from '../../lib/ui/icons';
import { P46_NAMES_AR, MISSION_NAMES_AR, DELIV, DELIV_AR, HORIZON, HORIZON_AR, PRIORITY, PRIORITY_AR, DEVIATION_DAYS, MAX_EXTRA, MAX_FINDINGS, MAX_KPIS, MAX_RECS, MAX_LESSONS, MAX_HANDOVER, MAX_OPEN, MISSION_SUMMARY_MAX, TEXT_MAX, LINE_MAX, SHORT_MAX, ACK_NOTE_MAX, ADDENDUM_MAX, fmtDayAr, missionStats, type MissionBody, type MissionComputed, type MissionPhrase, type Deliv } from '../../lib/reports/registry';

type Tok = () => Promise<string>;
async function api(tok: Tok | null, path: string, body?: any) { const tk = tok ? await tok() : ''; const h: any = { 'Content-Type': 'application/json' }; if (tk) h.Authorization = `Bearer ${tk}`; const r = await fetch(path, body ? { method: 'POST', headers: h, body: JSON.stringify(body) } : { headers: h, cache: 'no-store' }); return r.json().catch(() => ({ success: false, error: 'استجابة غير صالحة' })); }
const fmtT = (iso?: string | null) => (iso ? new Date(iso).toLocaleString('ar-SA-u-nu-latn-ca-gregory', { dateStyle: 'medium', timeStyle: 'short' }) : '');
const TONE: Record<string, string> = { draft: 'g', submitted: 'b', approved: 't', returned: 'o' };
const upd = <O,>(o: O, path: (string | number)[], v: any): O => { const c: any = Array.isArray(o) ? [...(o as any)] : { ...(o as any) }; if (path.length === 1) { c[path[0]] = v; return c; } c[path[0]] = upd(c[path[0]] ?? (typeof path[1] === 'number' ? [] : {}), path.slice(1), v); return c; };
const DTONE: Record<string, string> = { delivered: 't', partial: 'b', changed: 'o', not: 'r', '': 'g' };
const dev = (d: number | null) => (d === null ? '—' : d > DEVIATION_DAYS ? `تأخّر ${d} يومًا` : d > 0 ? `+${d}` : d < 0 ? `مبكّر ${-d}` : 'في موعده');
const MS_AR: Record<string, string> = { planned: 'مخطَّطة', in_progress: 'جارية', done: 'منجَزة' };
const SECS = ['بيانات المهمة', 'الملخّص التنفيذي', MISSION_NAMES_AR.matrix, MISSION_NAMES_AR.timeline, 'النتائج والأثر', 'التوصيات للجهة', 'التحدّيات والدروس', 'التسليم والمتابعة', 'الاعتماد'];

/* ───────── 1) بطاقات «مهماتك الموقَّعة» ───────── */
export function MissionCards({ missions, token }: { missions: any[]; token: Tok }) {
  const [busy, setBusy] = useState(''); const [err, setErr] = useState('');
  async function start(eid: string) { setBusy(eid); setErr(''); const j = await api(token, '/api/reports', { action: 'create_mission', engagement_id: eid }); setBusy(''); if (!j.success) { setErr(j.error || 'فشل'); return; } window.location.href = `/me/reports/${j.report.id}`; }
  return <section className="pt-box mr mr-cards" data-testid="mr-cards"><style dangerouslySetInnerHTML={{ __html: CSS }} />
    <h2><Icon name="shield" size={18} /> {P46_NAMES_AR.mission} <span className="mr-story">«{MISSION_NAMES_AR.story}»</span></h2>
    <p className="pt-muted">لكل عقد تعاون موقَّع مع أَثَر تقريرُ إنجاز واحد: مخرجات العقد تُسحب كما وُقِّعت، ومراحل الطلب بتواريخها؛ وتكتب أنت ما سُلِّم فعلًا، والنتائج، والتوصيات للجهة. الأجر لا يدخل التقرير.</p>
    <ul className="mr-cardl">{missions.map(m => <li key={m.engagement_id} data-testid="mr-card" data-status={m.status}>
      <div className="mr-cardh"><b>{m.title_ar}</b><span>{m.kind_ar}{m.org_ar ? ` · ${m.org_ar}` : ''}</span></div>
      <small className="pt-muted">{m.start_at ? `${fmtDayAr(m.start_at)} → ${m.end_at ? fmtDayAr(m.end_at) : '…'}` : 'بلا تاريخ'} · {m.deliverables} مخرجات في العقد · العقد: {m.status === 'active' ? 'جارٍ' : m.status === 'completed' ? 'أُنجز' : 'سُوّي'}{m.code ? <> · <span dir="ltr">{m.code}</span></> : ''}</small>
      <div className="mr-cardf">{m.report_id ? <Link className="pt-btn navy small" href={`/me/reports/${m.report_id}`} data-testid="mr-open">افتح تقرير الإنجاز · {m.report_status === 'approved' ? 'معتمَد' : m.report_status === 'submitted' ? 'بانتظار الاعتماد' : m.report_status === 'returned' ? 'أُعيد' : 'مسودّة'}</Link> : <button className="pt-btn gold small" type="button" onClick={() => start(m.engagement_id)} disabled={busy === m.engagement_id} data-testid="mr-start"><Icon name="plus" size={14} /> {busy === m.engagement_id ? '…' : MISSION_NAMES_AR.start}</button>}</div>
    </li>)}</ul>
    {err && <p className="mr-err" role="alert">{err}</p>}
  </section>;
}

/* ───────── 2) المحرّر ───────── */
export function MissionEditor({ id, token, mode = 'author', onBack }: { id: string; token: Tok; mode?: 'author' | 'admin'; onBack?: () => void }) {
  const [d, setD] = useState<any>(null); const [err, setErr] = useState(''); const [ok, setOk] = useState(''); const [busy, setBusy] = useState(''); const [dirty, setDirty] = useState(false);
  const [body, setBody] = useState<MissionBody | null>(null); const [sec, setSec] = useState(1); const [print, setPrint] = useState(false); const [phr, setPhr] = useState<{ phrases: MissionPhrase[]; note_ar: string } | null>(null); const [retNote, setRetNote] = useState(''); const [clientEmail, setClientEmail] = useState(''); const [addText, setAddText] = useState(''); const [sentUrl, setSentUrl] = useState('');
  const load = useCallback(async () => { const j = await api(token, `/api/reports?id=${encodeURIComponent(id)}`); if (!j?.success) { setErr(j?.error || 'تعذّر التحميل'); return; } setD(j); setBody(j.report.body); setDirty(false); setClientEmail(x => x || j.report.computed?.client_sent_to || j.report.computed?.client_email || ''); }, [token, id]);
  useEffect(() => { load(); }, [load]);
  useEffect(() => { const h = (e: BeforeUnloadEvent) => { if (dirty) { e.preventDefault(); e.returnValue = ''; } }; window.addEventListener('beforeunload', h); return () => window.removeEventListener('beforeunload', h); }, [dirty]);
  const r = d?.report; const c: MissionComputed | null = r?.computed || null; const editable = !!r?.can_edit; const ro = !editable;
  const setB = (path: (string | number)[], v: any) => { setBody(b => (b ? upd(b, path, v) : b)); setDirty(true); };
  const stats = useMemo(() => (body && c ? missionStats(body, c) : null), [body, c]);
  async function save(silent = false): Promise<boolean> { if (!body) return false; setBusy('save'); setErr(''); if (!silent) setOk(''); const j = await api(token, '/api/reports', { action: 'save', id, body }); setBusy(''); if (!j.success) { setErr(j.error || 'فشل الحفظ'); return false; } setD((x: any) => ({ ...x, report: j.report })); setBody(j.report.body); setDirty(false); if (!silent) setOk('حُفظ'); return true; }
  async function act(action: string, extra: any = {}) { setBusy(action); setErr(''); setOk(''); if (dirty && ['submit', 'recompute'].includes(action)) { const s = await save(true); if (!s) { setBusy(''); return; } } const j = await api(token, '/api/reports', { action, id, ...extra }); setBusy(''); if (!j.success) { setErr(j.error || 'فشل'); return; } await load(); if (action === 'send_client') setSentUrl(j.url || ''); setOk(action === 'submit' ? 'أُرسل — بانتظار اعتماد الطاقم' : action === 'approve' ? `اعتُمد — رمز التحقّق ${j.verify_code}` : action === 'return' ? 'أُعيد بملاحظة' : action === 'send_client' ? `أُرسل إلى ${j.to}` : action === 'addendum' ? 'أُلحق التصويب' : 'حُدِّثت الأرقام من العقد والطلب'); if (action === 'addendum') setAddText(''); }
  async function phrase() { setBusy('phrase'); setErr(''); const j = await api(token, '/api/reports', { action: 'mission_phrase', id, body }); setBusy(''); if (!j.success) { setErr(j.error || 'فشل'); return; } setPhr({ phrases: j.phrases || [], note_ar: j.note_ar || '' }); }
  function adopt(p: MissionPhrase) { if (!body) return; const add = (cur: string, max: number) => (cur ? cur + ' ' + p.text : p.text).slice(0, max); if (p.section === 'timeline') setB(['timeline', 'note'], add(body.timeline.note, TEXT_MAX)); else if (p.section === 'handover') setB(['handover', 'followup_note'], add(body.handover.followup_note, LINE_MAX)); else setB(['summary', 'executive'], add(body.summary.executive, MISSION_SUMMARY_MAX)); setPhr(x => (x ? { ...x, phrases: x.phrases.filter(y => y !== p) } : x)); }
  if (!d || !body || !c || !stats) return <main className="pt-main mr"><style dangerouslySetInnerHTML={{ __html: CSS }} /><section className="pt-box"><p className="pt-muted">{err || '…'}</p></section></main>;
  const S = d.status_ar; const late: string[] = r.late || []; const title = `${c.title_ar}${c.org_ar ? ` — ${c.org_ar}` : ''}`; const docs: any[] = Array.isArray(d.docs) ? d.docs : [];   // ر3-ب: وثائق معتمَدة للربط
  const inp = (path: (string | number)[], v: string, ph = '', max = TEXT_MAX, rows = 0) => rows ? <textarea value={v} onChange={e => setB(path, e.target.value.slice(0, max))} placeholder={ph} rows={rows} maxLength={max} readOnly={ro} /> : <input value={v} onChange={e => setB(path, e.target.value.slice(0, max))} placeholder={ph} maxLength={max} readOnly={ro} />;
  const strList = (path: (string | number)[], list: string[], max: number, ph: string, tid: string) => <div className="mr-list" data-testid={tid}>{list.map((t, i) => <div key={i} className="mr-li">{inp([...path, i], t, ph, LINE_MAX)}{editable && <button type="button" className="mr-x" aria-label="حذف" onClick={() => setB(path, list.filter((_, j) => j !== i))}>×</button>}</div>)}{editable && list.length < max && <button type="button" className="pt-btn ghost small" onClick={() => setB(path, [...list, ''])} data-testid={`${tid}-add`}><Icon name="plus" size={14} /> أضف</button>}</div>;
  if (print) return <MissionDoc r={{ ...r, body }} onClose={() => setPrint(false)} />;
  return <main className="pt-main mr mr-ed" data-testid="mr-editor" data-status={r.status}><style dangerouslySetInnerHTML={{ __html: CSS }} />
    <section className="pt-box mr-head">
      <div className="mr-head-top">
        <div><span className="pt-kicker"><Icon name="shield" size={14} /> {P46_NAMES_AR.mission} · «{MISSION_NAMES_AR.story}»</span>{mode === 'admin' ? <h2 className="mr-h">{title}</h2> : <h1>{title}</h1>}<p className="pt-muted">{c.kind_ar}{c.start_at ? ` · ${fmtDayAr(c.start_at)} → ${c.end_at ? fmtDayAr(c.end_at) : '…'}` : ''} · {c.expert_name} · <span className={`mr-chip ${TONE[r.status]}`} data-testid="mr-status">{S[r.status]}</span></p></div>
        <div className="mr-actions">
          {onBack ? <button className="pt-btn ghost small" type="button" onClick={onBack}><Icon name="arrow" size={14} /> القائمة</button> : <Link className="pt-btn ghost small" href="/me/reports"><Icon name="arrow" size={14} /> تقاريري</Link>}
          <button className="pt-btn ghost small" type="button" onClick={() => setPrint(true)} data-testid="mr-print"><Icon name="print" size={14} /> معاينة الطباعة</button>
          {editable && <button className="pt-btn ghost small" type="button" onClick={() => act('recompute')} disabled={!!busy} data-testid="mr-recompute"><Icon name="refresh" size={14} /> {P46_NAMES_AR.recompute}</button>}
          {editable && <button className="pt-btn navy small" type="button" onClick={() => save()} disabled={!!busy || !dirty} data-testid="mr-save"><Icon name="save" size={14} /> {busy === 'save' ? '…' : dirty ? 'احفظ' : 'محفوظ'}</button>}
          {editable && mode === 'author' && <button className="pt-btn gold small" type="button" onClick={() => act('submit')} disabled={!!busy} data-testid="mr-submit"><Icon name="send" size={14} /> {P46_NAMES_AR.submit}</button>}
          {r.can_decide && <button className="pt-btn gold small" type="button" onClick={() => act('approve')} disabled={!!busy} data-testid="mr-approve"><Icon name="check" size={14} /> {P46_NAMES_AR.approve}</button>}
        </div>
      </div>
      {r.can_decide && <div className="mr-return"><input value={retNote} onChange={e => setRetNote(e.target.value.slice(0, 400))} placeholder="ملاحظة الإعادة للخبير…" data-testid="mr-return-note" /><button className="pt-btn ghost small" type="button" onClick={() => act('return', { note: retNote })} disabled={!!busy || retNote.trim().length < 3} data-testid="mr-return"><Icon name="arrow" size={14} /> {P46_NAMES_AR.return}</button></div>}
      {r.status === 'returned' && r.return_note && <p className="mr-retbox" data-testid="mr-returned">أُعيد بملاحظة: {r.return_note}</p>}
      {r.status === 'approved' && <p className="mr-okbox" data-testid="mr-approved">معتمَد · {r.approved_name} · {fmtT(r.approved_at)} · رمز التحقّق <b dir="ltr">{r.verify_code}</b> · <Link href={`/verify/report/${r.verify_code}`}>صفحة التحقّق</Link>{body.ack ? <> · <b>{MISSION_NAMES_AR.ack}</b>: {body.ack.name} · {fmtT(body.ack.at)}</> : r.client_sent_at ? ` · أُرسل للجهة ${fmtT(r.client_sent_at)} — بانتظار الإقرار` : ''}</p>}
      {editable && r.missing?.length > 0 && <p className="mr-missing" data-testid="mr-missing">قبل الإرسال يلزم: {r.missing.join(' · ')}</p>}
      <div className="mr-kpis" data-testid="mr-kpis"><span className="b"><b data-testid="mr-k-deliv">{stats.delivered}/{stats.total}</b> مخرجات سُلِّمت</span><span><b>{c.milestones_done}/{c.milestones.length}</b> مراحل منجَزة</span>{c.milestones_late > 0 && <span className="o"><b>{c.milestones_late}</b> متأخّرة</span>}<span><b>{c.updates}</b> تحديثًا</span>{c.duration_days !== null && <span><b>{c.duration_days}</b> يومًا</span>}{c.sessions > 0 && <span><b>{c.sessions}</b> جلسة · {c.hours} ساعة</span>}<small>من العقد والطلب · {fmtT(c.at)}</small></div>
      <nav className="mr-secs" aria-label="أقسام التقرير">{SECS.map((s, i) => <button key={s} type="button" className={sec === i + 1 ? 'on' : ''} onClick={() => setSec(i + 1)} data-testid={`mr-sec-${i + 1}`}>{i + 1}. {s}</button>)}</nav>
    </section>

    {sec === 1 && <section className="pt-box mr-sec" data-testid="mr-s1"><h2>١. بيانات المهمة — من عقد التعاون وطلب الاستشارة</h2>
      <table className="mr-t"><tbody>
        <tr><th>المهمة</th><td>{c.title_ar}</td><th>النوع</th><td>{c.kind_ar}{c.mode ? ` · ${c.mode}` : ''}</td></tr>
        <tr><th>الجهة</th><td>{c.org_ar || '—'}{c.sector ? ` · ${c.sector}` : ''}{c.area ? ` · ${c.area}` : ''}</td><th>الخبير</th><td>{c.expert_name}{c.expert_title ? ` — ${c.expert_title}` : ''}</td></tr>
        <tr><th>المدة</th><td>{c.start_at ? `${fmtDayAr(c.start_at)} → ${c.end_at ? fmtDayAr(c.end_at) : '…'}` : '—'}{c.duration_days !== null ? ` (${c.duration_days} يومًا)` : ''}</td><th>عقد التعاون</th><td>{c.engagement_code ? <><span dir="ltr">{c.engagement_code}</span> · وقّعه الطرفان {c.member_signed_at ? fmtDayAr(String(c.member_signed_at).slice(0, 10)) : '—'}</> : <span data-testid="mr-noeng">طلب استشارة بلا عقد — المخرجات من عرض السعر المقبول</span>}</td></tr>
        <tr><th>نطاق العقد</th><td colSpan={3}>{c.scope_ar || '—'}</td></tr>
        {c.request_title && <tr><th>طلب الجهة</th><td colSpan={3}>{c.request_title}{c.request_goals ? ` — الأهداف: ${c.request_goals}` : ''}{c.request_timeline ? ` — الجدول المطلوب: ${c.request_timeline}` : ''}</td></tr>}
        {c.quote_scope && <tr><th>نطاق العرض المقبول</th><td colSpan={3}>{c.quote_scope}{c.quote_duration ? ` — المدة: ${c.quote_duration}` : ''}</td></tr>}
      </tbody></table>
      <label className="mr-lbl">السياق (اختياري — ما يلزم القارئ معرفته قبل التقرير){inp(['general', 'context'], body.general.context, 'خلفية المهمة · من شارك · أي قيود', TEXT_MAX, 3)}</label>
    </section>}

    {sec === 2 && <section className="pt-box mr-sec" data-testid="mr-s2"><h2>٢. الملخّص التنفيذي</h2>
      <label className="mr-lbl">ما الذي أُنجز، ولمن، وما أثره — في فقرة واحدة (≤ {MISSION_SUMMARY_MAX} حرفًا){inp(['summary', 'executive'], body.summary.executive, 'نُفِّذت المهمة…', MISSION_SUMMARY_MAX, 6)}</label>
      {editable && <div className="mr-ai"><div className="mr-row"><button className="pt-btn ghost small" type="button" onClick={phrase} disabled={!!busy} data-testid="mr-phrase"><Icon name="spark" size={14} /> {busy === 'phrase' ? '…' : MISSION_NAMES_AR.phrase}</button><small>من حالات المخرجات والمراحل والمدة فقط — بلا حكم ولا أجر؛ لا يُحفظ شيء حتى تعتمده.</small></div>
        {phr && <ul className="mr-phr" data-testid="mr-phrases">{phr.phrases.map((p, i) => <li key={i}><span><small className="mr-chip g">{p.section === 'timeline' ? MISSION_NAMES_AR.timeline : p.section === 'handover' ? 'التسليم' : 'الملخّص'}</small> {p.text}</span><button type="button" className="pt-btn navy small" onClick={() => adopt(p)}>أعتمد ←</button></li>)}{!phr.phrases.length && <li>لا جمل.</li>}<li className="mr-note">{phr.note_ar}</li></ul>}
      </div>}
    </section>}

    {sec === 3 && <section className="pt-box mr-sec" data-testid="mr-s3"><h2>٣. {MISSION_NAMES_AR.matrix} — كل مخرج كما وُقِّع، وما سُلِّم فعلًا</h2>
      <div className="mr-stats" data-testid="mr-stats"><span className="t"><b>{stats.delivered}</b> سُلِّم</span><span className="b"><b>{stats.partial}</b> جزئي</span><span className="o"><b>{stats.changed}</b> تغيّر بالاتفاق</span><span className="r"><b>{stats.not}</b> لم يُسلَّم</span>{stats.extra > 0 && <span><b>{stats.extra}</b> زيادة</span>}{stats.pct !== null && <span><b>{stats.pct}%</b> من المتّفق عليه</span>}</div>
      <div className="mr-scroll"><table className="mr-t mr-dl"><thead><tr><th>#</th><th>المخرج</th><th>المصدر</th><th>الحالة</th><th>الشاهد (رابط · ملف · وصف)</th><th>التاريخ</th><th>ملاحظة</th>{docs.length > 0 && <th>وثيقة أَثَر</th>}{editable && <th />}</tr></thead><tbody>
        {body.deliverables.map((dl, i) => <tr key={i} data-testid="mr-dl-row" data-status={dl.status || ''} data-source={dl.source}><td>{i + 1}</td><td>{dl.source === 'extra' ? inp(['deliverables', i, 'title'], dl.title, 'مخرج إضافي', SHORT_MAX) : <b>{dl.title}</b>}</td><td><small className={`mr-chip ${dl.source === 'extra' ? 'o' : 'g'}`}>{dl.source === 'contract' ? 'العقد' : dl.source === 'quote' ? 'العرض' : 'زيادة'}</small></td>
          <td><select value={dl.status} onChange={e => setB(['deliverables', i, 'status'], e.target.value as Deliv)} disabled={ro} data-testid="mr-dl-status" className={`mr-sel ${DTONE[dl.status]}`}><option value="">—</option>{DELIV.map(s => <option key={s} value={s}>{DELIV_AR[s]}</option>)}</select></td>
          <td>{inp(['deliverables', i, 'evidence'], dl.evidence, 'مثال: دليل الإجراءات v2 — سُلِّم بالبريد', LINE_MAX)}</td><td><input type="date" value={dl.date} onChange={e => setB(['deliverables', i, 'date'], e.target.value)} readOnly={ro} /></td><td>{inp(['deliverables', i, 'note'], dl.note, dl.status === 'changed' || dl.status === 'not' ? 'لماذا؟ وبموافقة من؟' : '', LINE_MAX)}</td>
          {docs.length > 0 && <td><select value={dl.doc_code || ''} onChange={e => setB(['deliverables', i, 'doc_code'], e.target.value)} disabled={ro} data-testid="mr-dl-doc" title="اختر وثيقة معتمَدة من أَثَر"><option value="">—</option>{docs.map((x: any) => <option key={x.code} value={x.code}>{x.kind === 'advisory' ? 'رأي' : 'دراسة'} · {x.code}{x.superseded ? ' (نُسخت)' : ''}</option>)}</select></td>}
          {editable && <td>{dl.source === 'extra' && <button type="button" className="mr-x" aria-label="حذف" onClick={() => setB(['deliverables'], body.deliverables.filter((_, j) => j !== i))}>×</button>}</td>}</tr>)}
        {!body.deliverables.length && <tr><td colSpan={8} className="pt-muted">العقد بلا مخرجات مكتوبة — أضف ما سُلِّم بوصفه «زيادة» واشرح.</td></tr>}
      </tbody></table></div>
      {editable && body.deliverables.filter(x => x.source === 'extra').length < MAX_EXTRA && <button type="button" className="pt-btn ghost small" onClick={() => setB(['deliverables'], [...body.deliverables, { title: '', source: 'extra', status: 'delivered', evidence: '', date: '', note: '' }])} data-testid="mr-add-extra"><Icon name="plus" size={14} /> مخرج إضافي خارج الاتفاق</button>}
      <p className="mr-key">مخرجات العقد والعرض لا تُحذف — تُشرح. «تغيّر بالاتفاق» و«لم يُسلَّم» يلزمهما ملاحظة. كل «سُلِّم» يلزمه شاهد.{docs.length > 0 ? ' عمود «وثيقة أَثَر» يربط المخرج برأي أو دراسة معتمَدة فتظهر «سلسلة الوثائق» في صفحة التحقّق.' : ''}</p>
    </section>}

    {sec === 4 && <section className="pt-box mr-sec" data-testid="mr-s4"><h2>٤. {MISSION_NAMES_AR.timeline} — المخطَّط مقابل الفعلي</h2>
      {c.milestones.length === 0 && <p className="pt-muted" data-testid="mr-noms">لا مراحل مسجَّلة على طلب الاستشارة — اكتب خطّ المهمة بكلماتك أدناه.</p>}
      {c.milestones.length > 0 && <div className="mr-scroll"><table className="mr-t"><thead><tr><th>#</th><th>المرحلة</th><th>الاستحقاق</th><th>الحالة</th><th>الإنجاز</th><th>الانحراف</th><th>السبب (يلزم إن تجاوز {DEVIATION_DAYS} أيام)</th></tr></thead><tbody>
        {c.milestones.map(m => <tr key={m.id} data-testid="mr-ms-row" data-late={late.includes(m.id) ? '1' : '0'}><td>{m.position}</td><td>{m.title}</td><td>{m.due_date ? fmtDayAr(m.due_date) : '—'}</td><td>{MS_AR[m.status] || m.status}</td><td>{m.done_at ? fmtDayAr(String(m.done_at).slice(0, 10)) : '—'}</td><td className={(m.deviation_days ?? 0) > DEVIATION_DAYS ? 'late' : (m.deviation_days ?? 0) < 0 ? 'early' : ''}>{dev(m.deviation_days)}</td><td>{late.includes(m.id) || body.timeline.reasons[m.id] ? inp(['timeline', 'reasons', m.id], body.timeline.reasons[m.id] || '', 'ما سبب الانحراف؟', LINE_MAX) : <span className="pt-muted">—</span>}</td></tr>)}
      </tbody></table></div>}
      <label className="mr-lbl">قراءة خطّ المهمة (اختياري){inp(['timeline', 'note'], body.timeline.note, 'كيف سار العمل زمنيًا؟ ما الذي سرّع أو أبطأ؟', TEXT_MAX, 3)}</label>
      {c.my_updates.length > 0 && <details className="mr-det"><summary>تحديثاتك المسجَّلة على الطلب ({c.my_updates.length}) — للرجوع</summary><ul>{c.my_updates.map((u, i) => <li key={i}>{u}</li>)}</ul></details>}
    </section>}

    {sec === 5 && <section className="pt-box mr-sec" data-testid="mr-s5"><h2>٥. النتائج والأثر</h2>
      <h3>النتائج (≤ {MAX_FINDINGS}) — كل نتيجة بشاهدها</h3>
      <div className="mr-list" data-testid="mr-findings">{body.results.findings.map((f, i) => <div key={i} className="mr-li mr-li2">{inp(['results', 'findings', i, 'text'], f.text, 'النتيجة', LINE_MAX)}{inp(['results', 'findings', i, 'evidence'], f.evidence, 'الشاهد', LINE_MAX)}{editable && <button type="button" className="mr-x" aria-label="حذف" onClick={() => setB(['results', 'findings'], body.results.findings.filter((_, j) => j !== i))}>×</button>}</div>)}{editable && body.results.findings.length < MAX_FINDINGS && <button type="button" className="pt-btn ghost small" onClick={() => setB(['results', 'findings'], [...body.results.findings, { text: '', evidence: '' }])} data-testid="mr-add-finding"><Icon name="plus" size={14} /> نتيجة</button>}</div>
      <h3>مؤشّرات قبل/بعد (اختياري · ≤ {MAX_KPIS}) — الفرق يُحسب</h3>
      <table className="mr-t mr-kpi" data-testid="mr-kpi"><thead><tr><th>المؤشّر</th><th>قبل</th><th>بعد</th><th>الوحدة</th><th>الفرق</th>{editable && <th />}</tr></thead><tbody>
        {body.results.kpis.map((k, i) => { const dd = stats.kpi_deltas[i]; return <tr key={i}><td>{inp(['results', 'kpis', i, 'name'], k.name, 'مثال: نسبة الإجراءات الموثَّقة', SHORT_MAX)}</td><td><input type="number" value={k.before ?? ''} onChange={e => setB(['results', 'kpis', i, 'before'], e.target.value === '' ? null : Number(e.target.value))} readOnly={ro} /></td><td><input type="number" value={k.after ?? ''} onChange={e => setB(['results', 'kpis', i, 'after'], e.target.value === '' ? null : Number(e.target.value))} readOnly={ro} /></td><td>{inp(['results', 'kpis', i, 'unit'], k.unit, '%', 20)}</td><td className={dd?.delta !== null && dd?.delta !== undefined ? (dd.delta > 0 ? 'up' : dd.delta < 0 ? 'down' : '') : ''} data-testid="mr-kpi-delta">{dd && dd.delta !== null ? `${dd.delta > 0 ? '+' : ''}${dd.delta}${dd.pct !== null ? ` (${dd.pct > 0 ? '+' : ''}${dd.pct}%)` : ''}` : '—'}</td>{editable && <td><button type="button" className="mr-x" aria-label="حذف" onClick={() => setB(['results', 'kpis'], body.results.kpis.filter((_, j) => j !== i))}>×</button></td>}</tr>; })}
      </tbody></table>
      {editable && body.results.kpis.length < MAX_KPIS && <button type="button" className="pt-btn ghost small" onClick={() => setB(['results', 'kpis'], [...body.results.kpis, { name: '', before: null, after: null, unit: '' }])} data-testid="mr-add-kpi"><Icon name="plus" size={14} /> مؤشّر</button>}
    </section>}

    {sec === 6 && <section className="pt-box mr-sec" data-testid="mr-s6"><h2>٦. التوصيات للجهة (≤ {MAX_RECS}) — بأفق وأولوية ومسؤول</h2>
      <div className="mr-scroll"><table className="mr-t" data-testid="mr-recs"><thead><tr><th>#</th><th>التوصية</th><th>الأفق</th><th>الأولوية</th><th>الجهة المسؤولة</th><th>الأثر المتوقَّع</th>{editable && <th />}</tr></thead><tbody>
        {body.recommendations.items.map((x, i) => <tr key={i} data-testid="mr-rec-row"><td>{i + 1}</td><td>{inp(['recommendations', 'items', i, 'text'], x.text, 'التوصية', LINE_MAX)}</td><td><select value={x.horizon} onChange={e => setB(['recommendations', 'items', i, 'horizon'], e.target.value)} disabled={ro}><option value="">—</option>{HORIZON.map(h => <option key={h} value={h}>{HORIZON_AR[h]}</option>)}</select></td><td><select value={x.priority} onChange={e => setB(['recommendations', 'items', i, 'priority'], e.target.value)} disabled={ro}><option value="">—</option>{PRIORITY.map(h => <option key={h} value={h}>{PRIORITY_AR[h]}</option>)}</select></td><td>{inp(['recommendations', 'items', i, 'owner'], x.owner, 'مثال: وحدة الجودة', SHORT_MAX)}</td><td>{inp(['recommendations', 'items', i, 'impact'], x.impact, '', LINE_MAX)}</td>{editable && <td><button type="button" className="mr-x" aria-label="حذف" onClick={() => setB(['recommendations', 'items'], body.recommendations.items.filter((_, j) => j !== i))}>×</button></td>}</tr>)}
      </tbody></table></div>
      {editable && body.recommendations.items.length < MAX_RECS && <button type="button" className="pt-btn ghost small" onClick={() => setB(['recommendations', 'items'], [...body.recommendations.items, { text: '', horizon: '', priority: '', owner: '', impact: '' }])} data-testid="mr-add-rec"><Icon name="plus" size={14} /> توصية</button>}
    </section>}

    {sec === 7 && <section className="pt-box mr-sec" data-testid="mr-s7"><h2>٧. التحدّيات والدروس</h2>
      <h3>التحدّيات وكيف عولجت (≤ {MAX_LESSONS})</h3>
      <div className="mr-list" data-testid="mr-challenges">{body.lessons.challenges.map((x, i) => <div key={i} className="mr-li mr-li2">{inp(['lessons', 'challenges', i, 'point'], x.point, 'التحدّي', LINE_MAX)}{inp(['lessons', 'challenges', i, 'handled'], x.handled, 'كيف عولج', LINE_MAX)}{editable && <button type="button" className="mr-x" aria-label="حذف" onClick={() => setB(['lessons', 'challenges'], body.lessons.challenges.filter((_, j) => j !== i))}>×</button>}</div>)}{editable && body.lessons.challenges.length < MAX_LESSONS && <button type="button" className="pt-btn ghost small" onClick={() => setB(['lessons', 'challenges'], [...body.lessons.challenges, { point: '', handled: '' }])} data-testid="mr-add-challenge"><Icon name="plus" size={14} /> تحدٍّ</button>}</div>
      <h3>دروس للمهمات القادمة (≤ {MAX_LESSONS})</h3>{strList(['lessons', 'lessons'], body.lessons.lessons, MAX_LESSONS, 'درس', 'mr-lessons')}
    </section>}

    {sec === 8 && <section className="pt-box mr-sec" data-testid="mr-s8"><h2>٨. التسليم والمتابعة</h2>
      <h3>ما سُلِّم للجهة (ملفات · جلسات · أدوات) (≤ {MAX_HANDOVER})</h3>{strList(['handover', 'items'], body.handover.items, MAX_HANDOVER, 'مثال: دليل الإجراءات — نسخة نهائية', 'mr-handover')}
      <h3>نقاط مفتوحة (≤ {MAX_OPEN})</h3>{strList(['handover', 'open'], body.handover.open, MAX_OPEN, 'ما بقي معلّقًا ومن يتولّاه', 'mr-open')}
      <div className="mr-row"><label>متابعة مقترَحة؟ <select value={body.handover.followup} onChange={e => setB(['handover', 'followup'], e.target.value)} disabled={ro} data-testid="mr-followup"><option value="">—</option><option value="yes">نعم</option><option value="no">لا</option></select></label>{body.handover.followup === 'yes' && inp(['handover', 'followup_note'], body.handover.followup_note, 'ما شكلها ومدتها؟', LINE_MAX)}</div>
      <label className="mr-lbl">ملاحظة إدارية لأَثَر (لا تراها الجهة){inp(['handover', 'admin_note'], body.handover.admin_note, 'ما يهمّ الطاقم فقط', TEXT_MAX, 3)}</label>
    </section>}

    {sec === 9 && <section className="pt-box mr-sec" data-testid="mr-s9"><h2>٩. الاعتماد — الطاقم يعتمد، والجهة تقرّ بالاستلام</h2>
      <table className="mr-t"><tbody><tr><th>الخبير</th><td>{r.author_name}{r.submitted_at ? ` · أرسل ${fmtT(r.submitted_at)}` : ' · لم يُرسل بعد'}</td></tr><tr><th>اعتماد أَثَر</th><td>{r.status === 'approved' ? `${r.approved_name} · ${fmtT(r.approved_at)} · رمز ${r.verify_code}` : S[r.status]}</td></tr><tr><th>{MISSION_NAMES_AR.ack}</th><td data-testid="mr-ack-state">{body.ack ? <><b>{body.ack.name}</b> · {fmtT(body.ack.at)}{body.ack.note ? <> · «{body.ack.note}»</> : ''}</> : r.client_sent_at ? `أُرسل للجهة ${fmtT(r.client_sent_at)} — بانتظار الإقرار` : 'لم يُرسل للجهة بعد'}</td></tr></tbody></table>
      {r.can_send_client && <div className="mr-client" data-testid="mr-send"><h3><Icon name="mail" size={16} /> {MISSION_NAMES_AR.send_client} — رابط قراءة وإقرار بلا دخول</h3><div className="mr-row"><input type="email" value={clientEmail} onChange={e => setClientEmail(e.target.value)} placeholder="بريد الجهة" data-testid="mr-client-email" /><button className="pt-btn gold small" type="button" onClick={() => act('send_client', { email: clientEmail })} disabled={!!busy || !clientEmail} data-testid="mr-send-client"><Icon name="send" size={14} /> {r.client_sent_at ? 'أعد الإرسال' : MISSION_NAMES_AR.send_client}</button></div>{sentUrl && <p className="mr-note" data-testid="mr-sent-url">الرابط: <a href={sentUrl} dir="ltr">{sentUrl}</a></p>}</div>}
      {r.can_addendum && <div className="mr-client" data-testid="mr-addendum"><h3><Icon name="doc" size={16} /> {MISSION_NAMES_AR.addendum} — يظهر مؤرَّخًا أسفل التقرير دون مسّ الأصل</h3><div className="mr-row"><input value={addText} onChange={e => setAddText(e.target.value.slice(0, ADDENDUM_MAX))} placeholder="نصّ التصويب…" data-testid="mr-addendum-text" /><button className="pt-btn ghost small" type="button" onClick={() => act('addendum', { text: addText })} disabled={!!busy || addText.trim().length < 10} data-testid="mr-addendum-btn">ألحِق</button></div></div>}
      {body.addenda?.length > 0 && <ul className="mr-addenda" data-testid="mr-addenda">{body.addenda.map((a, i) => <li key={i}><small>{fmtT(a.at)} · {a.by}</small><p>{a.text}</p></li>)}</ul>}
      <p className="mr-key">الاعتماد يُنهي عقد التعاون الجاري تلقائيًا (يصبح «أُنجزت») — أو يُنهي طلب الاستشارة إن كان التقرير بلا عقد — وتُحتسب المهمة في «ما شهده أَثَر» على بطاقة الخبير: «{MISSION_NAMES_AR.reported}». الأجر لا يظهر في التقرير ولا في صفحة التحقّق.</p>
    </section>}

    {(err || ok) && <p className={err ? 'mr-err' : 'mr-ok'} role="status" data-testid="mr-msg">{err || ok}</p>}
    <div className="mr-nav"><button className="pt-btn ghost small" type="button" onClick={() => setSec(s => Math.max(1, s - 1))} disabled={sec === 1}><Icon name="arrow" size={14} /> السابق</button><span>{sec} / 9</span><button className="pt-btn ghost small" type="button" onClick={() => setSec(s => Math.min(9, s + 1))} disabled={sec === 9}>التالي</button></div>
  </main>;
}

/* ───────── 3) الوثيقة (الطباعة A4 · ما تراه الجهة) ───────── */
export function MissionDoc({ r, onClose, client = false, ackSlot }: { r: any; onClose?: () => void; client?: boolean; ackSlot?: React.ReactNode }) {
  const c: MissionComputed = r.computed; const b: MissionBody = r.body; const s = r.stats || missionStats(b, c);
  return <div className="pr mr-doc" data-testid={client ? 'mr-client-doc' : 'mr-print-page'}><style dangerouslySetInnerHTML={{ __html: CSS + PRINT_CSS }} />
    {!client && <div className="pr-bar"><button className="pt-btn gold small" type="button" onClick={() => window.print()} data-testid="mr-print-btn"><Icon name="print" size={14} /> اطبع / احفظ PDF</button>{onClose && <button className="pt-btn ghost small" type="button" onClick={onClose}><Icon name="arrow" size={14} /> عودة للمحرّر</button>}<small>A4 — الأجر لا يظهر في هذه الوثيقة.</small></div>}
    <article className="pr-page">
      <header className="pr-head"><div><h1>{P46_NAMES_AR.mission}</h1><p>{c.title_ar}{c.org_ar ? ` — ${c.org_ar}` : ''}</p><p>{c.kind_ar}{c.start_at ? ` · ${fmtDayAr(c.start_at)} → ${c.end_at ? fmtDayAr(c.end_at) : '…'}` : ''}{c.duration_days !== null ? ` · ${c.duration_days} يومًا` : ''}</p></div><div className="pr-meta"><span>الخبير: {r.author_name}{c.expert_title ? ` — ${c.expert_title}` : ''}</span>{c.engagement_code && <span dir="ltr">عقد التعاون {c.engagement_code}</span>}{r.verify_code && <span dir="ltr">رمز التحقّق {r.verify_code}</span>}{r.approved_at && <span>اعتمده أَثَر: {r.approved_name} · {fmtT(r.approved_at)}</span>}</div></header>
      <h2>١. بيانات المهمة</h2>
      <table><tbody><tr><th>الجهة</th><td>{c.org_ar || '—'}</td><th>النوع</th><td>{c.kind_ar}{c.mode ? ` · ${c.mode}` : ''}</td></tr><tr><th>نطاق العقد</th><td colSpan={3}>{c.scope_ar || '—'}</td></tr>{c.request_title && <tr><th>طلب الجهة</th><td colSpan={3}>{c.request_title}{c.request_goals ? ` — ${c.request_goals}` : ''}</td></tr>}{b.general.context && <tr><th>السياق</th><td colSpan={3}>{b.general.context}</td></tr>}</tbody></table>
      <h2>٢. الملخّص التنفيذي</h2><p className="pr-p">{b.summary.executive || '—'}</p>
      <h2>٣. {MISSION_NAMES_AR.matrix}</h2>
      <p className="pr-key">سُلِّم {s.delivered} من {s.total} مخرجات متّفق عليها{s.partial ? ` · ${s.partial} جزئي` : ''}{s.changed ? ` · ${s.changed} تغيّر بالاتفاق` : ''}{s.not ? ` · ${s.not} لم يُسلَّم` : ''}{s.extra ? ` · ${s.extra} زيادة خارج الاتفاق` : ''}</p>
      <table><thead><tr><th>#</th><th>المخرج</th><th>المصدر</th><th>الحالة</th><th>الشاهد</th><th>التاريخ</th><th>ملاحظة</th></tr></thead><tbody>{b.deliverables.map((d, i) => <tr key={i}><td>{i + 1}</td><td>{d.title}</td><td>{d.source === 'contract' ? 'العقد' : d.source === 'quote' ? 'العرض' : 'زيادة'}</td><td>{d.status ? DELIV_AR[d.status] : '—'}</td><td>{d.evidence || '—'}</td><td>{d.date ? fmtDayAr(d.date) : '—'}</td><td>{d.note || ''}{d.doc_code ? <> <small dir="ltr">[{d.doc_code}]</small></> : null}</td></tr>)}</tbody></table>
      <h2>٤. {MISSION_NAMES_AR.timeline}</h2>
      {c.milestones.length > 0 && <table><thead><tr><th>#</th><th>المرحلة</th><th>الاستحقاق</th><th>الإنجاز</th><th>الانحراف</th><th>السبب</th></tr></thead><tbody>{c.milestones.map(m => <tr key={m.id}><td>{m.position}</td><td>{m.title}</td><td>{m.due_date ? fmtDayAr(m.due_date) : '—'}</td><td>{m.done_at ? fmtDayAr(String(m.done_at).slice(0, 10)) : MS_AR[m.status] || m.status}</td><td>{dev(m.deviation_days)}</td><td>{b.timeline.reasons[m.id] || ''}</td></tr>)}</tbody></table>}
      {b.timeline.note && <p className="pr-p">{b.timeline.note}</p>}{!c.milestones.length && !b.timeline.note && <p className="pr-p">—</p>}
      <h2>٥. النتائج والأثر</h2>
      {b.results.findings.length > 0 && <table><thead><tr><th>#</th><th>النتيجة</th><th>الشاهد</th></tr></thead><tbody>{b.results.findings.map((f, i) => <tr key={i}><td>{i + 1}</td><td>{f.text}</td><td>{f.evidence || '—'}</td></tr>)}</tbody></table>}
      {b.results.kpis.length > 0 && <table><thead><tr><th>المؤشّر</th><th>قبل</th><th>بعد</th><th>الفرق</th></tr></thead><tbody>{b.results.kpis.map((k, i) => { const dd = s.kpi_deltas[i]; return <tr key={i}><td>{k.name}</td><td>{k.before ?? '—'}{k.unit}</td><td>{k.after ?? '—'}{k.unit}</td><td>{dd && dd.delta !== null ? `${dd.delta > 0 ? '+' : ''}${dd.delta}${k.unit}${dd.pct !== null ? ` (${dd.pct > 0 ? '+' : ''}${dd.pct}%)` : ''}` : '—'}</td></tr>; })}</tbody></table>}
      {!b.results.findings.length && !b.results.kpis.length && <p className="pr-p">—</p>}
      <h2>٦. التوصيات للجهة</h2>
      <table><thead><tr><th>#</th><th>التوصية</th><th>الأفق</th><th>الأولوية</th><th>المسؤول</th><th>الأثر المتوقَّع</th></tr></thead><tbody>{b.recommendations.items.map((x, i) => <tr key={i}><td>{i + 1}</td><td>{x.text}</td><td>{x.horizon ? HORIZON_AR[x.horizon] : '—'}</td><td>{x.priority ? PRIORITY_AR[x.priority] : '—'}</td><td>{x.owner || '—'}</td><td>{x.impact || ''}</td></tr>)}{!b.recommendations.items.length && <tr><td colSpan={6}>—</td></tr>}</tbody></table>
      <h2>٧. التحدّيات والدروس</h2>
      {b.lessons.challenges.length > 0 && <table><thead><tr><th>التحدّي</th><th>كيف عولج</th></tr></thead><tbody>{b.lessons.challenges.map((x, i) => <tr key={i}><td>{x.point}</td><td>{x.handled || '—'}</td></tr>)}</tbody></table>}
      {b.lessons.lessons.length > 0 && <ul className="pr-ul">{b.lessons.lessons.map((l, i) => <li key={i}>{l}</li>)}</ul>}{!b.lessons.challenges.length && !b.lessons.lessons.length && <p className="pr-p">—</p>}
      <h2>٨. التسليم والمتابعة</h2>
      <table><tbody><tr><th>ما سُلِّم</th><td>{b.handover.items.length ? <ul className="pr-ul">{b.handover.items.map((l, i) => <li key={i}>{l}</li>)}</ul> : '—'}</td></tr><tr><th>نقاط مفتوحة</th><td>{b.handover.open.length ? <ul className="pr-ul">{b.handover.open.map((l, i) => <li key={i}>{l}</li>)}</ul> : '—'}</td></tr><tr><th>متابعة مقترَحة</th><td>{b.handover.followup === 'yes' ? `نعم${b.handover.followup_note ? ` — ${b.handover.followup_note}` : ''}` : b.handover.followup === 'no' ? 'لا' : '—'}</td></tr>{!client && b.handover.admin_note && <tr><th>ملاحظة إدارية (داخلية)</th><td>{b.handover.admin_note}</td></tr>}</tbody></table>
      <h2>٩. الاعتماد</h2>
      <table className="pr-sign"><thead><tr><th>الخبير</th><th>اعتماد أَثَر</th><th>{MISSION_NAMES_AR.ack}</th></tr></thead><tbody><tr><td>{r.author_name}<br /><small>{r.submitted_at ? fmtT(r.submitted_at) : ''}</small></td><td>{r.approved_name || '—'}<br /><small>{r.approved_at ? `${fmtT(r.approved_at)} · معتمَد إلكترونيًا` : 'بانتظار الاعتماد'}</small></td><td>{b.ack ? <>{b.ack.name}<br /><small>{fmtT(b.ack.at)}{b.ack.note ? ` · «${b.ack.note}»` : ''}</small></> : <small>—</small>}</td></tr></tbody></table>
      {b.addenda?.length > 0 && <><h2>إلحاقات مؤرَّخة</h2><ul className="pr-ul">{b.addenda.map((a, i) => <li key={i}><small>{fmtT(a.at)} · {a.by}:</small> {a.text}</li>)}</ul></>}
      {ackSlot}
      <footer className="pr-foot"><p>{P46_NAMES_AR.axis} · {P46_NAMES_AR.official} — أَثَر</p>{r.verify_code && <p>للتحقّق: /verify/report/{r.verify_code}</p>}</footer>
    </article>
  </div>;
}

/* ───────── 4) الجهة: قراءة + إقرار بالاستلام (بلا دخول) ───────── */
export function MissionClient({ code, k }: { code: string; k: string }) {
  const [d, setD] = useState<any>(undefined); const [name, setName] = useState(''); const [note, setNote] = useState(''); const [busy, setBusy] = useState(false); const [err, setErr] = useState(''); const [done, setDone] = useState(false);
  const load = useCallback(() => fetch(`/api/reports?verify=${encodeURIComponent(code)}&k=${encodeURIComponent(k)}`, { cache: 'no-store' }).then(r => r.json()).then(j => setD(j?.report || null)).catch(() => setD(null)), [code, k]);
  useEffect(() => { load(); }, [load]);
  async function ack(e: React.FormEvent) { e.preventDefault(); setBusy(true); setErr(''); const j = await fetch('/api/reports', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ action: 'ack', code, k, name, note }) }).then(r => r.json()).catch(() => ({ success: false, error: 'تعذّر الإرسال' })); setBusy(false); if (!j.success) { setErr(j.error || 'فشل'); return; } setDone(true); load(); }
  if (d === undefined) return <main className="pt-main mr"><style dangerouslySetInnerHTML={{ __html: CSS }} /><section className="pt-box"><p className="pt-muted">…</p></section></main>;
  if (d === null) return <main className="pt-main mr" data-testid="mr-client-bad"><style dangerouslySetInnerHTML={{ __html: CSS }} /><section className="pt-box"><h1>الرابط غير صالح أو انتهى</h1><p className="pt-muted">اطلب من أَثَر إعادة إرسال رابط التقرير. <Link href={`/verify/report/${code}`}>صفحة التحقّق العامة</Link></p></section></main>;
  const slot = <section className="mr-ackbox" data-testid="mr-ackbox">{d.body?.ack || done ? <p className="mr-okbox" data-testid="mr-acked"><Icon name="check" size={16} /> أُقرّ باستلام هذا التقرير{d.body?.ack ? ` — ${d.body.ack.name} · ${fmtT(d.body.ack.at)}` : ''}. شكرًا لكم.</p> : <form onSubmit={ack} className="mr-ackform"><h3><Icon name="mail" size={16} /> {MISSION_NAMES_AR.ack} — استلامٌ لا تقييم</h3><p className="pt-muted">بالضغط تُثبتون أن الجهة استلمت تقرير إنجاز المهمة بصيغته المعتمَدة. يمكنكم إضافة ملاحظة قصيرة تُحفظ مع التقرير.</p><div className="mr-row"><input value={name} onChange={e => setName(e.target.value.slice(0, 120))} placeholder="اسم المُقِرّ وصفته" required data-testid="mr-ack-name" /><input value={note} onChange={e => setNote(e.target.value.slice(0, ACK_NOTE_MAX))} placeholder="ملاحظة (اختياري)" data-testid="mr-ack-note" /><button className="pt-btn gold" type="submit" disabled={busy || name.trim().length < 2} data-testid="mr-ack-btn"><Icon name="check" size={16} /> {busy ? '…' : MISSION_NAMES_AR.ack_btn}</button></div>{err && <p className="mr-err" role="alert">{err}</p>}</form>}</section>;
  return <main className="pt-main mr" data-testid="mr-client"><style dangerouslySetInnerHTML={{ __html: CSS }} /><p className="mr-clienthead"><Icon name="shield" size={14} /> نسخة الجهة من {P46_NAMES_AR.mission} — معتمَدة من أَثَر · <Link href={`/verify/report/${code}`}>صفحة التحقّق العامة</Link> · <button type="button" className="mr-linkbtn" onClick={() => window.print()}>اطبع / PDF</button></p><MissionDoc r={d} client ackSlot={slot} /></main>;
}

